import math
from fractions import Fraction

def f(m, n, alpha):
    # m*ceil(n*alpha) - n*floor(m*alpha)
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha)

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    return f(m, n, alpha) == k

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False
    if is_pretty(m - n, n, alpha, k) or is_pretty(m, n - m, alpha, k):
        return False
    return True

def count_cool_pairs(alpha, k, limit):
    cool_pairs = []
    for m in range(1, limit + 1):
        for n in range(1, limit + 1):
            if is_cool(m, n, alpha, k):
                cool_pairs.append((m, n))
    return len(cool_pairs), cool_pairs

# Test for k = 1, 2, 3, 4, 5 with different alphas
alphas = [math.sqrt(2), math.pi, math.e]
ks = [1, 2, 3, 4, 5]
for k in ks:
    results = []
    for alpha in alphas:
        # What limit should we use?
        # f(m, n, alpha) = n{m*alpha} - m{n*alpha} + m.
        # If m is very large, f(m, n, alpha) might be large.
        # But if n is also large, it's not obvious.
        # Let's try a reasonable limit and see.
        count, pairs = count_cool_pairs(alpha, k, 100)
        results.append(count)
    print(f"k={k}, counts={results}")

